def land(note: str, anchor: str) -> None:
    text = WORKLOG.read_text()
    if anchor in text:
        print(f"already landed: {anchor[:60]}")
        return
    if not text.endswith("\n"):
        text += "\n"
    WORKLOG.write_text(text + note)
    print(f"landed: {anchor[:60]}")


